// ═══════════════════════════════════════════════
// INQUIRY — Build Dynamic Service List (API Version)
// ═══════════════════════════════════════════════

const organizationId = Number(
  $('⚙️ INIT — Normalize & Extract Request')
    .first()
    .json
    .organizationId
);

const organizations = $json.results || [];

const organization = organizations.find(
  org => org.id === organizationId
);

if (!organization) {
  return [{
    json: {
      responseType: 'NO_SERVICES',
      message: '⚠️ لم يتم العثور على الجهة.',
      buttons: [
        { label: '🔙 رجوع للجهات', action: 'INQUIRY_START' },
        { label: '🏠 القائمة الرئيسية', action: 'MENU' }
      ]
    }
  }];
}

const services = organization.services || [];

if (services.length === 0) {
  return [{
    json: {
      responseType: 'NO_SERVICES',
      message: `⚠️ لا توجد خدمات متاحة حالياً لـ\n"${organization.name}"`,
      buttons: [
        { label: '🔙 رجوع للجهات', action: 'INQUIRY_START' },
        { label: '🏠 القائمة الرئيسية', action: 'MENU' }
      ]
    }
  }];
}

const serviceButtons = services.map(service => ({

    label: service.name,

    action:"INQUIRY_SERVICE_DETAIL",

    serviceId: service.id,

    organizationId: organization.id,

    organizationName: organization.name

}));

serviceButtons.push({
  label: '🔙 رجوع للجهات',
  action: 'INQUIRY_START'
});

serviceButtons.push({
  label: '🏠 القائمة الرئيسية',
  action: 'MENU'
});

return [{
  json: {
    responseType: 'SERVICE_LIST',

    message: `📋 خدمات ${organization.name}
━━━━━━━━━━━━━━━━━━━━━━━━━━
اختر الخدمة لعرض التفاصيل:`,

    buttons: serviceButtons,

    organizationId: organization.id
  }
}];

// ═══════════════════════════════════════════════
// INQUIRY — Format Service Detail Card (API)
// ═══════════════════════════════════════════════

const service = $input.first().json;

if (!service.id) {

  return [{
    json:{
      responseType:"NOT_FOUND",

      message:"⚠️ لم يتم العثور على بيانات الخدمة.",

      buttons:[
        {
          label:"🔙 رجوع",
          action:"INQUIRY_START"
        },
        {
          label:"🏠 القائمة الرئيسية",
          action:"MENU"
        }
      ]
    }
  }];

}

// Required Documents
const docs = service.required_documents || [];

const docsText =
docs.length
? docs.map(doc => `• ${doc.name}`).join('\n')
: "لا توجد مستندات مطلوبة";

// Duration
const duration =
service.duration
? service.duration.substring(0,5)
: "-";

// Price
const price =
`${service.price} ${service.currency}`;

// Organization
const organizationId = service.organization;
const organizationName = service.organization_name;

// Message
const message = `📄 تفاصيل الخدمة
━━━━━━━━━━━━━━━━━━━━━━━━━━

🏛️ الجهة: ${organizationName}

📌 الخدمة:
${service.name}

📝 الوصف:
${service.description}

📋 المستندات المطلوبة:
${docsText}

⏳ المدة:
${duration}

💰 الرسوم:
${price}`;

return [{

json:{

responseType:"SERVICE_DETAIL",

message,

serviceId:service.id,

organizationId:organizationId,

buttons:[

{
label:"🎫 احجز دور لهذه الخدمة",
action:"BOOK_START",
serviceId:service.id,
organizationId:organizationId
},

{
label:"🔙 رجوع للخدمات",
action:"INQUIRY_SELECT_DEPT",
organizationId:organizationId
},

{
label:"🏠 القائمة الرئيسية",
action:"MENU"
}

]

}

}];

const booking = $('🌐 API — Create Appointment').first().json;
const branch = $('🌐 API — Get Branch Details').first().json;

return {
  responseType: "BOOKING_SUCCESS",

  message:
`🎉 تم تأكيد حجزك بنجاح

تم تسجيل موعدك بنجاح، ويسعدنا خدمتك. ✅

━━━━━━━━━━━━━━━━━━━━━━

📍 الفرع
${branch.name}

🛎 الخدمة
${booking.counter.service.name}

📅 التاريخ
${booking.date}

🕒 الموعد
${booking.start_time.substring(0,5)}

💰 الرسوم
${booking.amount_to_pay ?? booking.counter.service.price} ${booking.counter.service.currency}

🆔 رقم الحجز
#${booking.id}

━━━━━━━━━━━━━━━━━━━━━━

⏳ يرجى الحضور قبل الموعد بـ 10 دقائق.

📄 تأكد من إحضار أي مستندات مطلوبة لإتمام الخدمة.

💚 شكرًا لاستخدام SmartIQ Assistant.
نتمنى لك يومًا سعيدًا.`,

  buttons: [
    {
      label: "📄 حجوزاتي",
      action: "MY_BOOKINGS"
    },
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ]
};

// ═══════════════════════════════════════════════
// OUTPUT — Unified Response Aggregator
// Normalizes all branch outputs into one format
// ═══════════════════════════════════════════════

const data = $input.first().json;

const response = {
  ok:           true,
  responseType: data.responseType || 'UNKNOWN',
  message:      data.message      || '',
  buttons:      data.buttons      || [],

  serviceId: data.serviceId,
  branchId: data.branchId,
  organizationId: data.organizationId,

  timestamp:    new Date().toISOString()
};

// Include booking summary if present
if (data.bookingId) {
  response.booking = {
    id:          data.bookingId,
    queueNumber: data.queueNumber,
    department:  data.department,
    service:     data.serviceName
  };
}

return [response];

const arabicNames = {
  "Egyptian Post": "🏤 البريد المصري",
  "General Traffic Department": "🚗 الإدارة العامة للمرور",
  "Civil Affairs Sector": "🪪 قطاع الأحوال المدنية",
  "Passports & Immigration Department": "🛂 مصلحة الجوازات والهجرة",
  "National Organization for Social Insurance": "🛡️ الهيئة القومية للتأمينات الاجتماعية"
};

const buttons = [];

for (const org of $json.results) {

  if (!org.is_active) continue;

  buttons.push({
    label: arabicNames[org.name] ?? org.name,

    action: "INQUIRY_SELECT_DEPT",

    organizationId: org.id
  });

}

buttons.push({
  label: "🔙 رجوع",
  action: "MENU"
});

return [
{
json:{
responseType:"DEPT_SELECTOR",

message:`🏢 اختر الجهة الحكومية
━━━━━━━━━━━━━━━━━━━━━━━━━━
ستظهر لك الخدمات المتاحة بها:`,

buttons
}
}
];

// ═══════════════════════════════════════════════
// BOOKING — Format Organizations (API)
// Builds booking department selector from API
// ═══════════════════════════════════════════════

const arabicNames = {
  "Egyptian Post": "🏤 البريد المصري",
  "General Traffic Department": "🚗 الإدارة العامة للمرور",
  "Civil Affairs Sector": "🪪 قطاع الأحوال المدنية",
  "Passports & Immigration Department": "🛂 مصلحة الجوازات والهجرة",
  "National Organization for Social Insurance": "🛡️ الهيئة القومية للتأمينات الاجتماعية"
};

const buttons = [];

// API returns:
// {
//   count,
//   results: [...]
// }

for (const org of ($json.results || [])) {

  // Skip inactive organizations if the field exists
  if (org.is_active === false) continue;

  buttons.push({
    label: arabicNames[org.name] ?? org.name,

    action: "BOOK_SELECT_DEPT",

    organizationId: org.id
  });

}

buttons.push({
  label: "🔙 رجوع",
  action: "MENU"
});

return [{
  json: {
    responseType: "BOOK_DEPT_SELECT",

    message:
`🎫 حجز دور — اختر الجهة
━━━━━━━━━━━━━━━━━━━━━━━━━━
ستحصل على رقم دور فور الاختيار:`,

    buttons
  }
}];

const buttons = [];

for (const branch of ($json.results || [])) {

  if (!branch.is_active) continue;

  if (!branch.services || branch.services.length === 0) continue;

  buttons.push({
    label: branch.name,
    action: "BOOK_SELECT_BRANCH",
    branchId: branch.id,
    organizationId: branch.organization
  });

}

buttons.push({
  label: "🔙 رجوع",
  action: "BOOK_START"
});

buttons.push({
  label: "🏠 القائمة الرئيسية",
  action: "MENU"
});

return [{
  json: {
    responseType: "BOOK_BRANCH_SELECT",

    message:
`🏢 اختر الفرع
━━━━━━━━━━━━━━━━━━━━━━━━━━`,

    buttons
  }
}];

const branchId = Number(
  $('⚙️ INIT — Normalize & Extract Request')
    .first()
    .json
    .branchId
);

const branches = $json.results || [];

const branch = branches.find(b => b.id === branchId);

if (!branch) {
  return [{
    responseType: 'NOT_FOUND',
    message: '⚠️ لم يتم العثور على الفرع.',
    buttons: [
      {
        label: '🔙 رجوع للفروع',
        action: 'BOOK_SELECT_DEPT'
      },
      {
        label: '🏠 القائمة الرئيسية',
        action: 'MENU'
      }
    ]
  }];
}

return [{
  branch
}];

const branch = $input.first().json.branch;

const buttons = branch.services.map(service => ({
  label: service.name,
  action: "BOOK_SELECT_DATE",
  serviceId: service.id,
  organizationId: branch.organization,
  branchId: branch.id,
  branchName: branch.name
}));

buttons.push({
  label: "🔙 رجوع للفروع",
  action: "BOOK_SELECT_DEPT",
  organizationId: branch.organization
});

buttons.push({
  label: "🏠 القائمة الرئيسية",
  action: "MENU"
});

return [{
  responseType: "BOOK_SERVICE_SELECT",

  message:
`📋 خدمات ${branch.name}
━━━━━━━━━━━━━━━━━━━━━━━━━━
اختر الخدمة:`,

  buttons
}];

return [
  {
    json: {
      responseType: "INPUT_DATE",
      message: "📅 اختر تاريخ الحجز",
      serviceId: $input.first().json.serviceId,
      branchId: $input.first().json.branchId,
      organizationId: $input.first().json.organizationId,
    },
  },
];

const serviceId = Number(
  $('⚙️ INIT — Normalize & Extract Request')
    .first()
    .json
    .serviceId
);

const counters = $json.results || [];

const counter = counters.find(c =>
  c.is_operational &&
  c.service &&
  Number(c.service.id) === serviceId
);

if (!counter) {
  return [
    {
      json: {
        found: false
      }
    }
  ];
}

return [
  {
    json: {
      found: true,
      counterId: counter.id,
      counter,
    }
  }
];

const request = $('⚙️ INIT — Normalize & Extract Request')
  .first()
  .json;

// بيانات الفرع
const branch = $('🔧 BOOKING — Resolve Selected Branch')
  .first()
  .json
  .branch;

const branchName = branch.name;

// بيانات الخدمة
const service = branch.services.find(
  s => Number(s.id) === Number(request.serviceId)
);

const serviceName = service?.name || "الخدمة المطلوبة";

return [
  {
    json: {
      responseType: "BOOK_NO_COUNTER",

      message:
`⚠️ خدمة "${serviceName}"

غير متاحة للحجز حالياً فى:

📍 ${branchName}

يرجى اختيار فرع آخر يقدم نفس الخدمة.`,

      buttons: [
        {
          label: "🔙 اختيار فرع آخر",
          action: "BOOK_CHANGE_BRANCH",
          organizationId: request.organizationId,
          serviceId: request.serviceId,
          branchId: request.branchId
        },
        {
          label: "🏠 القائمة الرئيسية",
          action: "MENU"
        }
      ]
    }
  }
];

const branchId = Number(
  $('⚙️ INIT — Normalize & Extract Request')
    .first()
    .json
    .branchId
);

const branches = $json.results || [];

const branch = branches.find(b => b.id === branchId);

if (!branch) {
  return [{
    responseType: 'NOT_FOUND',
    message: '⚠️ لم يتم العثور على الفرع.',
    buttons: [
      {
        label: '🔙 رجوع للفروع',
        action: 'BOOK_SELECT_DEPT'
      },
      {
        label: '🏠 القائمة الرئيسية',
        action: 'MENU'
      }
    ]
  }];
}

return [{
  branch
}];

const request = $('⚙️ INIT — Normalize & Extract Request')
  .first().json;

const currentBranchId = Number(request.branchId);

const branches = $json.results || [];

// استبعد الفرع الحالي
const filteredBranches = branches.filter(
  branch => Number(branch.id) !== currentBranchId
);

// رجع كل فرع كـ Item مستقل
return filteredBranches.map(branch => ({
  json: {
    branchId: branch.id,
    branchName: branch.name,
    branch,
    serviceId: Number(request.serviceId),
    organizationId: Number(request.organizationId),
    currentBranchId,
  }
}));

const counters = $json.results || [];

const serviceId = Number(
  $('⚙️ INIT — Normalize & Extract Request')
    .first()
    .json
    .serviceId
);

const counter = counters.find(c =>
  Number(c.service.id) === serviceId &&
  c.is_operational === true
);
const branchInfo = $('🔧 BOOKING — Find Alternative Branches')
  .all()
  .find(
    item => Number(item.json.branchId) === Number(counter?.branch)
  )?.json;
if (!counter) {
  return {
    valid: false
  };
}

return {
  valid: true,
  branchId: counter.branch,
  branchName: branchInfo.branchName,
  organizationId: branchInfo.organizationId,
  serviceId: branchInfo.serviceId,
  counterId: counter.id
};

const buttons = [];

for (const item of $input.all()) {

  buttons.push({
    label: `📍 ${item.json.branchName}`,
    action: "BOOK_SELECT_DATE",
    branchId: item.json.branchId,
    serviceId: item.json.serviceId,
    organizationId: item.json.organizationId,
  });

}

return {
  responseType: "BOOK_CHANGE_BRANCH",

  message:
`⚠️ الخدمة غير متاحة للحجز في الفرع الذي اخترته حالياً.

يمكنك اختيار أحد الفروع التالية لإكمال الحجز:`,

  buttons
};

const data = $json;

const counterData = $('❓ IF — Counter Found').first().json;

const requestData = $('⚙️ INIT — Normalize & Extract Request').first().json;

const buttons = (data.slots || []).map(slot => ({
  label: `🕒 ${slot.start}`,
  action: "BOOK_CONFIRM",

  date: data.date,
  time: slot.start,

  counterId: counterData.counterId,
  branchId: requestData.branchId,
  branchName: requestData.branchName,
  serviceId: requestData.serviceId,
  organizationId: requestData.organizationId
}));

return {
  responseType: "BOOK_SELECT_TIME",
  message: "🕒 اختر وقت الحجز:",
  buttons
};

const request =
  $('⚙️ INIT — Normalize & Extract Request').first().json;
const error =
  $json.non_field_errors?.[0] ||
  $json.detail ||
  "";

let response = {
  responseType: "BOOKING_ERROR",
  message: "❌ حدث خطأ أثناء إتمام الحجز.\nيرجى المحاولة مرة أخرى.",
  buttons: [
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ]
};

if (error === "You already have a pending appointment for this counter.") {

  response.responseType = "BOOKING_ALREADY_EXISTS";

  response.message =
`📌 لديك حجز قائم بالفعل لهذه الخدمة.

لا يمكنك إنشاء حجز جديد قبل انتهاء أو إلغاء الحجز الحالي.

يمكنك متابعة حالة الحجز من خلال "حجوزاتي".`;

  response.buttons = [
    {
      label: "📄 حجوزاتي",
      action: "MY_BOOKINGS"
    },
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ];

}

else if (error === "This slot was just booked.") {

  response.responseType = "BOOKING_SLOT_TAKEN";

  response.message =
`⏳ للأسف تم حجز هذا الموعد بواسطة مستخدم آخر منذ لحظات.

يرجى اختيار موعد آخر.`;

  response.buttons = [
    {
      label: "🕒 اختيار وقت آخر",
      action: "BOOK_SELECT_TIME",

      branchId: request.branchId,
      counterId: request.counterId,
      serviceId: request.serviceId,
      organizationId: request.organizationId,
      date: request.date
    },
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ];

}

else if (error === "This counter is currently unavailable.") {

  response.responseType = "COUNTER_UNAVAILABLE";

  response.message =
`⚠️ هذا الشباك غير متاح حالياً.

  يرجى اختيار فرع آخر لإكمال الحجز.`;

  response.buttons = [
    {
      label: "📍 اختيار فرع آخر",
      action: "BOOK_CHANGE_BRANCH",

      branchId: request.branchId,
      counterId: request.counterId,
      serviceId: request.serviceId,
      organizationId: request.organizationId,
      date: request.date
    },
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ];

}

else if (error === "You have another appointment scheduled during this time frame.") {

  response.responseType = "TIME_CONFLICT";

  response.message =
`📅 لديك موعد آخر في نفس التوقيت.

يرجى اختيار وقت مختلف.`;

  response.buttons = [
    {
      label: "🕒 اختيار وقت آخر",
      action: "BOOK_SELECT_TIME",

      branchId: request.branchId,
      counterId: request.counterId,
      serviceId: request.serviceId,
      organizationId: request.organizationId,
      date: request.date
    },
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ];

}

else if (error === "The selected time slot is not available for this service on this date.") {

  response.responseType = "INVALID_SLOT";

  response.message =
`⚠️ الموعد الذي اخترته لم يعد متاحاً.

يرجى اختيار موعد آخر.`;

  response.buttons = [
    {
      label: "🕒 اختيار وقت آخر",
      action: "BOOK_SELECT_TIME",

      branchId: request.branchId,
      counterId: request.counterId,
      serviceId: request.serviceId,
      organizationId: request.organizationId,
      date: request.date
    },
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ];

}

else if (error === "User does not have a client profile.") {

  response.responseType = "CLIENT_PROFILE_REQUIRED";

  response.message =
  `⚠️ لا يمكن إتمام الحجز لأن حسابك غير مكتمل.

يرجى إكمال بيانات حسابك أولاً.`;

  response.buttons = [
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ];

}

else if ($json.detail === "Authentication credentials were not provided.") {

  response.responseType = "AUTH_REQUIRED";

  response.message =
`🔒 انتهت صلاحية جلسة تسجيل الدخول.

يرجى تسجيل الدخول مرة أخرى.`;

  response.buttons = [
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ];

}

return response;

const data = $json;

const bookings = data.results || [];

if (bookings.length === 0) {
  return {
    responseType: "MY_BOOKINGS",

    message:
`📭 لا توجد لديك أي حجوزات حالياً.`,

    buttons: [
      {
        label: "🏠 القائمة الرئيسية",
        action: "MENU"
      }
    ]
  };
}

let message = "📋 حجوزاتك الحالية\n\n";

for (const booking of bookings) {

  message +=
`🆔 #${booking.id}

🛎 ${booking.counter.service.name}
📅 ${booking.date}
🕒 ${booking.start_time.substring(0,5)}

──────────────

`;

}

return {

  responseType: "MY_BOOKINGS",

  message,

  buttons: [
    {
      label: "🏠 القائمة الرئيسية",
      action: "MENU"
    }
  ]
};

return {
  responseType: "NO_AVAILABLE_BRANCH",

  message:
`😔 عذرًا

لا يوجد حالياً أي فرع يقدم هذه الخدمة للحجز.

قد يكون السبب:
• جميع الشبابيك غير متاحة.
• الخدمة متوقفة مؤقتاً.

يرجى المحاولة مرة أخرى لاحقاً أو اختيار خدمة أخرى.`,

